package net.battlespades.session;
import java.util.*;
import java.util.concurrent.*;
import net.battlespades.player.PlayerLife;
/** Source /bots administration on the ordinary permission-checked command queue. */
final class HostedBotCommands {
    private final StandardMatchDomain match;private final ApplicationHost host;
    HostedBotCommands(StandardMatchDomain match,ApplicationHost host){this.match=match;this.host=host;match.social().commands().register(new CommandRegistry.Command("bots",List.of(),true,false,"/bots status|fill <count>|add <count> [team]|remove <count|name|all>|difficulty <casual|normal|hard|mixed>|debug <on|off|name>","Manage isolated server-owned bots",c->{run(c);return CompletableFuture.completedFuture(null);}));}
    private void notice(CommandRegistry.Context c,String text){match.social().notice(c.player(),text);}
    private void run(CommandRegistry.Context c){String sub=c.args().isEmpty()?"status":c.args().getFirst().toLowerCase(Locale.ROOT);if(sub.equals("status")){var active=host.bots();if(active.isEmpty()){notice(c,"Bots disabled (0 active)");return;}var d=active.get();var s=d.status();notice(c,String.format(Locale.ROOT,"Bots=%d worker=%s pid=%s recycles=%d crashes=%d stalls=%d silence=%.1fs frames=%d intents=%d terrain=%d",d.players().size(),s.running()?"up":"down",s.processId()==null?"-":s.processId(),s.plannedRecycles(),s.crashRestarts(),s.stalledRestarts(),s.intentSilenceSeconds(),s.queuedFrames(),s.queuedIntents(),s.pendingTerrainCells()));return;}
        var director=host.ensureBots();switch(sub){
            case "fill"->{if(c.args().size()!=2){notice(c,"Usage: /bots fill <count>");return;}int target;try{target=Math.clamp(Integer.parseInt(c.args().get(1)),0,host.playerLimit());}catch(NumberFormatException invalid){notice(c,"Bot fill count must be an integer");return;}director.backfill(target);notice(c,"Bot backfill target set to "+target);}
            case "add"->{if(c.args().size()<2){notice(c,"Usage: /bots add <count> [team]");return;}int count;try{count=Math.clamp(Integer.parseInt(c.args().get(1)),0,12);}catch(NumberFormatException invalid){notice(c,"Bot add count must be an integer");return;}Integer team=null;if(c.args().size()>=3){team=switch(c.args().get(2).toLowerCase(Locale.ROOT)){case "1","team1","blue"->2;case "2","team2","green"->3;default->null;};if(team==null){notice(c,"Team must be 1/blue or 2/green");return;}}director.manualPopulation(count);int added=0;for(int i=0;i<count;i++)if(director.add(team,null,null,null).isPresent())added++;else break;notice(c,"Added "+added+" bot(s)");}
            case "remove"->{if(c.args().size()!=2){notice(c,"Usage: /bots remove <count|name|all>");return;}director.manualPopulation(0);String token=c.args().get(1);List<PlayerLife> candidates;if(token.equalsIgnoreCase("all"))candidates=director.players();else{try{int count=Math.max(0,Integer.parseInt(token));candidates=director.players().stream().limit(count).toList();}catch(NumberFormatException name){String wanted=token.toLowerCase(Locale.ROOT),prefix=director.namePrefix().toLowerCase(Locale.ROOT);candidates=director.players().stream().filter(p->p.name().toLowerCase(Locale.ROOT).startsWith(wanted)||!prefix.isEmpty()&&p.name().toLowerCase(Locale.ROOT).startsWith(prefix+wanted)).limit(1).toList();}}int removed=0;for(var p:candidates)if(director.remove(p,false,true))removed++;notice(c,"Removed "+removed+" bot(s); objective-protected bots were kept");}
            case "difficulty"->{if(c.args().size()!=2||!Set.of("casual","normal","hard","mixed").contains(c.args().get(1).toLowerCase(Locale.ROOT))){notice(c,"Usage: /bots difficulty <casual|normal|hard|mixed>");return;}String value=c.args().get(1).toLowerCase(Locale.ROOT);director.difficulty(value);notice(c,"Bot difficulty set to "+value+" for new profiles");}
            case "debug"->{if(c.args().size()!=2){notice(c,"Usage: /bots debug <on|off|name>");return;}String token=c.args().get(1);if(token.equalsIgnoreCase("on")||token.equalsIgnoreCase("off")){boolean enabled=token.equalsIgnoreCase("on");director.debug(enabled);notice(c,"Bot debug visualization "+(enabled?"enabled":"disabled"));return;}var rows=director.debugSnapshot(token);if(rows.isEmpty()){notice(c,"Bot debug is disabled or no matching bot exists");return;}var r=rows.getFirst();String text=r.get("name")+" action="+r.get("action")+" edge="+r.get("affordance")+" goal="+r.get("goal")+" path="+r.get("path");notice(c,text.substring(0,Math.min(240,text.length())));}
            default->notice(c,"Unknown /bots subcommand");
        }
    }
}
